import { colors, useTheme } from '@/theme'
import { Eye, CheckCircle, Hammer } from 'lucide-react-native'
import { Badge } from '../../../components/primitives/Badge'

export type Environment = 'Published' | 'Preview' | 'Builder'

interface EnvironmentTagProps {
	environment: Environment
}

const getEnvironmentColor = (
	environment: Environment
): 'blue' | 'yellow' | 'green' => {
	switch (environment) {
		case 'Builder':
			return 'blue'
		case 'Preview':
			return 'yellow'
		case 'Published':
			return 'green'
	}
}

export const EnvironmentTag = ({ environment }: EnvironmentTagProps) => {
	const { theme } = useTheme()

	const getEnvironmentIcon = () => {
		switch (environment) {
			case 'Builder':
				return <Hammer size={16} color={colors[theme].blue[600]} />
			case 'Preview':
				return <Eye size={16} color={colors[theme].yellow[600]} />
			case 'Published':
				return <CheckCircle size={16} color={colors[theme].green[600]} />
		}
	}

	return (
		<Badge color={getEnvironmentColor(environment)} icon={getEnvironmentIcon()}>
			{environment}
		</Badge>
	)
}
